//: API レート制限 (生成時 標準装備)
// インメモリ・スライディングウィンドウ方式。単一インスタンス構成 (next start /
// ローカル運用) で有効。サーバーレス/マルチインスタンス本番では Upstash Redis 等の
// 共有ストアへ差し替えること (インターフェイスは同一)。
//
// 使い方 (API route / server action の冒頭):
//   const rl = checkRateLimit(`signin:${ip}`, { limit: 5, windowMs: 60_000 });
//   if (!rl.ok) return NextResponse.json({ error: 'リクエストが多すぎます。しばらく待ってからお試しください。' }, { status: 429 });

type Bucket = { timestamps: number[] };

const buckets = new Map<string, Bucket>();

export interface RateLimitOptions {
  /** ウィンドウ内に許可する最大リクエスト数 (既定 30) */
  limit?: number;
  /** ウィンドウ長ミリ秒 (既定 60秒) */
  windowMs?: number;
}

export interface RateLimitResult {
  ok: boolean;
  remaining: number;
  retryAfterMs: number;
}

export function checkRateLimit(key: string, opts: RateLimitOptions = {}): RateLimitResult {
  const limit = opts.limit ?? 30;
  const windowMs = opts.windowMs ?? 60_000;
  const now = Date.now();

  const bucket = buckets.get(key) ?? { timestamps: [] };
  bucket.timestamps = bucket.timestamps.filter((t) => now - t < windowMs);

  if (bucket.timestamps.length >= limit) {
    const oldest = bucket.timestamps[0];
    buckets.set(key, bucket);
    return { ok: false, remaining: 0, retryAfterMs: windowMs - (now - oldest) };
  }

  bucket.timestamps.push(now);
  buckets.set(key, bucket);

  // メモリ肥大防止: 古いキーを定期的に間引く
  if (buckets.size > 10_000) {
    for (const [k, b] of buckets) {
      if (b.timestamps.length === 0 || now - b.timestamps[b.timestamps.length - 1] > windowMs) {
        buckets.delete(k);
      }
    }
  }

  return { ok: true, remaining: limit - bucket.timestamps.length, retryAfterMs: 0 };
}
